<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Api\BaseApiController; use App\Models\Banner; use Illuminate\Http\Request;
class BannerController extends BaseApiController { public function index(){return $this->ok(Banner::orderBy('banner_type')->orderBy('sort_order')->get());} public function show(Banner $banner){return $this->ok($banner);} public function store(Request $r){$d=$r->validate(['banner_type'=>'required|in:hero,promo','title'=>'nullable|string|max:255','alt_text'=>'required|string|max:255','image_url'=>'required|string','link_url'=>'nullable|string','sort_order'=>'integer','is_active'=>'boolean']);return $this->ok(Banner::create($d),201);} public function update(Request $r,Banner $banner){$banner->update($r->validate(['banner_type'=>'sometimes|in:hero,promo','title'=>'nullable|string|max:255','alt_text'=>'sometimes|string|max:255','image_url'=>'sometimes|string','link_url'=>'nullable|string','sort_order'=>'integer','is_active'=>'boolean']));return $this->ok($banner);} public function destroy(Banner $banner){$banner->delete();return $this->ok();} }
